function renderCurriculumSummaries(){const genesis=$('genesis-summary');genesis.replaceChildren();const gCards=make('div',{class:'curriculum-summary'});const arcs=[...new Set((curriculum.genesis||[]).map(x=>x.arc).filter(Boolean))];for(const arc of arcs){const items=curriculum.genesis.filter(x=>x.arc===arc);gCards.append(make('div',{class:'summary-card'},[make('p',{class:'eyebrow',text:items.length+' sessions · '+items.reduce((s,x)=>s+(Number(x.hours)||0),0)+' reference hours'}),make('h3',{text:arc}),make('p',{text:items[0]?.objective||'Explore the linked learning sequence.'})]));}genesis.append(gCards);if(curriculum.clockRule)genesis.append(make('p',{class:'storage-note',text:asText(curriculum.clockRule)}));const teacher=$('teacher-summary');teacher.replaceChildren();const t=curriculum.teacher||{};if(t.hourBudgetOrigin)teacher.append(make('p',{text:asText(t.hourBudgetOrigin),class:'prose'}));if(t.hyperBusyOrigin)teacher.append(make('p',{text:asText(t.hyperBusyOrigin),class:'prose'}));if(t.schedules?.length){const cards=make('div',{class:'curriculum-summary'});for(const entry of t.schedules){if(typeof entry==='string'){cards.append(make('div',{class:'summary-card'},[make('p',{text:entry})]));}else{const name=entry.name||entry.title||entry.mode||'Study route';cards.append(make('div',{class:'summary-card'},[make('h3',{text:name}),make('p',{text:Object.entries(entry).filter(([k])=>!['name','title','mode'].includes(k)).map(([k,v])=>asText(v)).join(' · ')})]));}}teacher.append(cards);}renderImmersion();}
