async function load(){route(true);const files=['questionnaire','demo-answers','sources','curriculum','interview-engine','weaving-atlas'];const results=await Promise.allSettled(files.map(async name=>{const response=await fetch('data/'+name+'.json',{cache:'no-cache'});if(!response.ok)throw Error(name+' returned '+response.status);return response.json();}));const failed=[];results.forEach((result,index)=>{if(result.status!=='fulfilled'){failed.push(files[index]);return;}const data=result.value;if(index===0)questionnaire=data;if(index===1)demo=data;if(index===2)sources=Array.isArray(data)?data:data.sources||[];if(index===3)curriculum=data;if(index===4)interviewEngine=data;if(index===5)weavingAtlas=data;});questionnaire.domains=questionnaire.domains||[];questionnaire.lenses=questionnaire.lenses||[];curriculum.genesis=curriculum.genesis||[];curriculum.teacher=curriculum.teacher||{modules:[]};curriculum.teacher.modules=curriculum.teacher.modules||[];questions=questionnaire.domains.flatMap(d=>(d.questions||[]).map(q=>({...q,domain:d})));questionById=new Map(questions.map(q=>[q.id,q]));dataReady=true;try{const saved=localStorage.getItem(STORAGE_KEY);if(saved){const parsed=JSON.parse(saved);if(parsed.consent?.browserStorage===true){workbook=validateImport(parsed);workbook.consent.browserStorage=true;status('Restored your previously saved browser workbook.');}}}catch(e){status('A previous browser workbook could not be restored: '+e.message+' Its stored file has not been removed.');}
$('question-total').textContent=questions.length||'288';$('question-mode').value=mode;renderStorage();renderDomains();renderTags();renderQuestions();renderObserverRecords();renderSources();initialiseDeep();initialiseAtlas();renderCurriculumSummaries();renderCurriculum('genesis');renderCurriculum('teacher');const guide=$('lens-guide');for(const lens of questionnaire.lenses)guide.append(make('div',{class:'lens-guide-item'},[make('b',{text:lens.id}),make('span',{text:lens.prompt})]));if(failed.length){$('load-status').classList.add('error');$('load-status').textContent='Could not open: '+failed.join(', ')+'. Use the complete reading guides, or serve this folder through a local web server rather than opening index.html as a file.';}else{$('load-status').hidden=true;}document.dispatchEvent(new CustomEvent('aura-studio-ready',{detail:{questions:questions.length,domains:questionnaire.domains.length}}));}
$('save-locally').addEventListener('change',e=>{workbook.consent.browserStorage=e.target.checked;if(!e.target.checked){try{localStorage.removeItem(STORAGE_KEY);status('Browser-saved copy removed. Current work remains in memory until you leave this page.');}catch(error){status('The browser copy could not be removed. Use this browser’s site-data settings.');}}else status('Browser saving enabled for this personal workbook.');dirty();renderStorage();});
$('export-json').addEventListener('click',exportWorkbook);$('export-md').addEventListener('click',exportMarkdown);$('import-json').addEventListener('change',e=>importWorkbook(e.target.files[0]));$('clear-workbook').addEventListener('click',async()=>{if(!await confirmAction('Clear your personal workbook?','This removes this studio’s answers, interview turns, saved observer events and review marks from memory and this browser. Other sites and files are untouched. Export first if you want a copy.','Clear my workbook'))return;workbook=emptyWorkbook();try{localStorage.removeItem(STORAGE_KEY);}catch(e){status('Memory cleared, but browser storage could not be removed. Check this browser’s site-data settings.');}renderStorage();renderQuestions();renderObserverRecords();renderCurriculum('genesis');renderCurriculum('teacher');clearObserver();resetDeep();status('Personal workbook cleared. The public question library and demo answers are unchanged.');});
$('question-search').addEventListener('input',e=>{query=e.target.value;page=0;renderQuestions();});$('question-mode').addEventListener('change',e=>{mode=e.target.value;page=0;renderQuestions();});$('toggle-demos').addEventListener('click',()=>{showDemos=!showDemos;renderQuestions();});document.querySelector('[data-demo-shortcut]').addEventListener('click',()=>{showDemos=true;renderQuestions();});$('source-search').addEventListener('input',e=>renderSources(e.target.value));
$('observer-example').addEventListener('click',async()=>{const current=observerFormRecord();if(Object.entries(current).some(([key,value])=>!['basis','format','simulation'].includes(key)&&typeof value==='string'&&value.trim())&&!await confirmAction('Replace the event draft?','The fictional example will replace this unsaved draft. Saved events in your workbook are kept.','Load fictional example'))return;loadObserverExample();});$('observer-new').addEventListener('click',async()=>{const current=observerFormRecord();if(Object.entries(current).some(([key,value])=>!['basis','format','simulation'].includes(key)&&typeof value==='string'&&value.trim())&&!await confirmAction('Start a blank event?','The current unsaved event draft will be cleared. Events already added to your workbook are kept.','Start blank event'))return;clearObserver();});$('observer-form').elements.namedItem('basis').addEventListener('change',e=>{$('observer-simulation').hidden=!(observerDraftSimulation||e.target.value==='fictional-simulation');});$('observer-form').addEventListener('submit',e=>{e.preventDefault();const event=observerFormRecord();if(!event.title||(!event.environment&&!event.attention&&!event.narrator&&!event.correction)){$('observer-status').textContent='Add a title and at least one observer stream or participant correction.';return;}event.id=typeof crypto.randomUUID==='function'?crypto.randomUUID():'event-'+Date.now()+'-'+Math.random().toString(36).slice(2);event.savedAt=new Date().toISOString();workbook.observers.push(event);dirty();renderObserverRecords();$('observer-status').textContent='Event added to your workbook. '+(workbook.consent.browserStorage?'It is saved in this browser.':'Export your workbook before leaving to keep it.');});$('export-observer').addEventListener('click',()=>{const event=observerFormRecord();download('aura-observer-event-'+stamp()+'.json',JSON.stringify({...event,exportedAt:new Date().toISOString()},null,2));$('observer-status').textContent='Event exported with its source and simulation label.';});
